&lt;li&gt;&lt;span data-sheets-value=&quot;{&amp;quot;1&amp;quot;:2,&amp;quot;2&amp;quot;:&amp;quot;3+ years experience selling technology solutions in a B2B model&amp;quot;}&quot; data-sheets-userformat=&quot;{&amp;quot;2&amp;quot;:15105,&amp;quot;3&amp;quot;:{&amp;quot;1&amp;quot;:0},&amp;quot;11&amp;quot;:4,&amp;quot;12&amp;quot;:0,&amp;quot;14&amp;quot;:{&amp;quot;1&amp;quot;:2,&amp;quot;2&amp;quot;:0},&amp;quot;15&amp;quot;:&amp;quot;\&amp;quot;Helvetica Neue\&amp;quot;, Helvetica, Arial, sans-serif&amp;quot;,&amp;quot;16&amp;quot;:10}&quot;&gt;&lt;span data-sheets-value=&quot;{&amp;quot;1&amp;quot;:2,&amp;quot;2&amp;quot;:&amp;quot;Experience orchestrating cross-functional teams, including Partners sales and marketing teams to plan and execute a territory business plan&amp;quot;}&quot; data-sheets-userformat=&quot;{&amp;quot;2&amp;quot;:15105,&amp;quot;3&amp;quot;:{&amp;quot;1&amp;quot;:0},&amp;quot;11&amp;quot;:4,&amp;quot;12&amp;quot;:0,&amp;quot;14&amp;quot;:{&amp;quot;1&amp;quot;:2,&amp;quot;2&amp;quot;:0},&amp;quot;15&amp;quot;:&amp;quot;\&amp;quot;Helvetica Neue\&amp;quot;, Helvetica, Arial, sans-serif&amp;quot;,&amp;quot;16&amp;quot;:10}&quot;&gt;&lt;span data-sheets-value=&quot;{&amp;quot;1&amp;quot;:2,&amp;quot;2&amp;quot;:&amp;quot;Experience supporting and building relationships highly preferred&amp;quot;}&quot; data-sheets-userformat=&quot;{&amp;quot;2&amp;quot;:15105,&amp;quot;3&amp;quot;:{&amp;quot;1&amp;quot;:0},&amp;quot;11&amp;quot;:4,&amp;quot;12&amp;quot;:0,&amp;quot;14&amp;quot;:{&amp;quot;1&amp;quot;:2,&amp;quot;2&amp;quot;:0},&amp;quot;15&amp;quot;:&amp;quot;\&amp;quot;Helvetica Neue\&amp;quot;, Helvetica, Arial, sans-serif&amp;quot;,&amp;quot;16&amp;quot;:10}&quot;&gt;Experience supporting and building relationships highly preferred&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
